// hybrid_moe_bench: single-layer, batch-1 MoE expert FFN with expert-granular GPU-hit / CPU-miss dispatch.
// Real Granite weights (Q4_K experts) from GGUF, real routing (top-8 ids + weights) replayed from trace JSONL.
// Paths:
//   gpu_ref   : all 32 experts resident on GPU, one mul_mat_id graph over the 8 selected experts (llama.cpp formulation)
//   cpu_all   : same graph on the ggml CPU backend over the (pinned) host copy of all experts
//   hybrid    : K GPU slots (slot table expert->slot|-1); hits -> GPU graph over slots, misses -> CPU graph over host copy,
//               GPU launched async, CPU computes concurrently, then y = y_gpu + y_cpu (each side applies its own routing weights,
//               so every selected expert's weight is applied exactly once)
//   upload    : llama.cpp --moe-cache-mib style: misses are copied H2D into LRU slots before the token, then all 8 on GPU
// Slot policies: static (top-K by PREFILL-phase routing frequency; decode tokens are not used to choose) and LRU
// (cold start; after each token every miss is admitted, evicting the least recently used slot; H2D cost timed separately).
// Numerics: fp64 reference from dequantized Q4_K weights and unquantized activations; see README for the tolerance rule.
#include "ggml.h"
#include "ggml-alloc.h"
#include "ggml-backend.h"
#include "ggml-cpu.h"
#include "ggml-cuda.h"
#include "gguf.h"

#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <map>
#include <random>
#include <sstream>
#include <string>
#include <thread>
#include <vector>

static const int NE = 32, NU = 8;   // experts per layer, experts used per token (checked against tensor shapes)
static int D = 1024, F = 512;        // hidden, expert FFN dim (read from tensors)

static double now_us() {
    return std::chrono::duration<double, std::micro>(std::chrono::steady_clock::now().time_since_epoch()).count();
}
#define CHECK(c) do { if (!(c)) { fprintf(stderr, "CHECK failed %s:%d: %s\n", __FILE__, __LINE__, #c); exit(1); } } while (0)

struct Token { int ids[NU]; float w[NU]; int xi; std::string src; };

// ---------------------------------------------------------------- trace parsing (minimal, format is fixed)
static bool parse_line(const std::string & l, int layer_want, const char * phase_want, Token & t) {
    auto geti = [&](const char * key, int & v) { auto p = l.find(key); if (p == std::string::npos) return false; v = atoi(l.c_str() + p + strlen(key)); return true; };
    int layer; if (!geti("\"layer\":", layer) || layer != layer_want) return false;
    auto pp = l.find("\"phase\":\""); if (pp == std::string::npos) return false;
    if (l.compare(pp + 9, strlen(phase_want), phase_want) != 0) return false;
    auto pe = l.find("\"experts\":["), pw = l.find("\"weights\":["); CHECK(pe != std::string::npos && pw != std::string::npos);
    const char * s = l.c_str() + pe + 11; char * e;
    for (int i = 0; i < NU; i++) { t.ids[i] = (int) strtol(s, &e, 10); s = e + 1; }
    s = l.c_str() + pw + 11;
    for (int i = 0; i < NU; i++) { t.w[i] = strtof(s, &e); s = e + 1; }
    return true;
}
static std::vector<Token> load_trace(const std::string & path, int layer, const char * phase, const std::string & tag) {
    std::ifstream f(path); CHECK(f.good()); std::string l; std::vector<Token> v;
    while (std::getline(f, l)) { Token t; if (parse_line(l, layer, phase, t)) { t.src = tag; t.xi = 0; v.push_back(t); } }
    return v;
}

// ---------------------------------------------------------------- MoE graph (same op sequence as llama.cpp build_moe_ffn, SILU gated, no bias)
struct MoeG {
    ggml_context * ctx = nullptr; ggml_cgraph * gf = nullptr; ggml_gallocr_t ga = nullptr;
    ggml_tensor *x = nullptr, *ids = nullptr, *w = nullptr, *out = nullptr; int n = 0;
    void free_() { if (ga) ggml_gallocr_free(ga); if (ctx) ggml_free(ctx); ga = nullptr; ctx = nullptr; }
};
static MoeG build_moe(ggml_backend_t be, ggml_tensor * Wg, ggml_tensor * Wu, ggml_tensor * Wd, int n) {
    MoeG g; g.n = n;
    ggml_init_params ip = { ggml_tensor_overhead() * 64 + ggml_graph_overhead(), nullptr, true };
    g.ctx = ggml_init(ip);
    g.x = ggml_new_tensor_3d(g.ctx, GGML_TYPE_F32, D, 1, 1); ggml_set_input(g.x);
    g.ids = ggml_new_tensor_2d(g.ctx, GGML_TYPE_I32, n, 1); ggml_set_input(g.ids);
    g.w = ggml_new_tensor_3d(g.ctx, GGML_TYPE_F32, 1, n, 1); ggml_set_input(g.w);
    ggml_tensor * gate = ggml_mul_mat_id(g.ctx, Wg, g.x, g.ids);   // [F, n, 1]
    ggml_tensor * up   = ggml_mul_mat_id(g.ctx, Wu, g.x, g.ids);   // [F, n, 1]
    ggml_tensor * act  = ggml_swiglu_split(g.ctx, gate, up);       // silu(gate) * up
    ggml_tensor * dn   = ggml_mul_mat_id(g.ctx, Wd, act, g.ids);   // [D, n, 1]
    ggml_tensor * ex   = ggml_mul(g.ctx, dn, g.w);                 // routing weights applied here, once per expert
    ggml_tensor * out  = ggml_view_2d(g.ctx, ex, D, 1, ex->nb[2], 0);
    for (int i = 1; i < n; i++) out = ggml_add(g.ctx, out, ggml_view_2d(g.ctx, ex, D, 1, ex->nb[2], i * ex->nb[1]));
    if (n == 1) out = ggml_cont(g.ctx, out);
    ggml_set_output(out); g.out = out;
    g.gf = ggml_new_graph(g.ctx); ggml_build_forward_expand(g.gf, out);
    g.ga = ggml_gallocr_new(ggml_backend_get_default_buffer_type(be));
    CHECK(ggml_gallocr_alloc_graph(g.ga, g.gf));
    return g;
}

// ---------------------------------------------------------------- global state
struct Weights { ggml_tensor *g, *u, *d; };
static ggml_backend_t be_gpu, be_cpu;
static Weights Wh;            // host (pinned) full copy, 32 experts
static Weights Wf;            // GPU full copy, 32 experts (reference)
static std::vector<std::vector<float>> X;     // activation vectors
static float *h_x, *h_w, *h_y;  static int32_t * h_ids;    // pinned staging
static std::vector<float> y_cpu_buf(1024);
static MoeG cpu_g[NU + 1];    // CPU graphs over host weights, n = 1..8
static MoeG ref_g;            // GPU graph over full weights, n = 8

struct Sample { double total, gpu, cpu, wait, admit; int hits; };

static void run_gpu_launch(MoeG & g, const float * x, const int * ids, const float * w) {
    memcpy(h_x, x, D * 4); memcpy(h_ids, ids, g.n * 4); memcpy(h_w, w, g.n * 4);
    ggml_backend_tensor_set_async(be_gpu, g.x, h_x, 0, D * 4);
    ggml_backend_tensor_set_async(be_gpu, g.ids, h_ids, 0, g.n * 4);
    ggml_backend_tensor_set_async(be_gpu, g.w, h_w, 0, g.n * 4);
    CHECK(ggml_backend_graph_compute_async(be_gpu, g.gf) == GGML_STATUS_SUCCESS);
    ggml_backend_tensor_get_async(be_gpu, g.out, h_y, 0, D * 4);
}
static void run_cpu(MoeG & g, const float * x, const int * ids, const float * w, float * y) {
    memcpy(g.x->data, x, D * 4); memcpy(g.ids->data, ids, g.n * 4); memcpy(g.w->data, w, g.n * 4);
    CHECK(ggml_backend_graph_compute(be_cpu, g.gf) == GGML_STATUS_SUCCESS);
    memcpy(y, g.out->data, D * 4);
}

// ---------------------------------------------------------------- slot cache
struct Slots {
    int K = 0; Weights W{}; ggml_context * ctx = nullptr; ggml_backend_buffer_t buf = nullptr;
    std::vector<int> slot_of, expert_in; std::vector<long> last_use; long clock = 0;
    MoeG g[NU + 1];
    void init(int k) {
        K = k; ggml_init_params ip = { ggml_tensor_overhead() * 4, nullptr, true }; ctx = ggml_init(ip);
        W.g = ggml_new_tensor_3d(ctx, Wh.g->type, Wh.g->ne[0], Wh.g->ne[1], K);
        W.u = ggml_new_tensor_3d(ctx, Wh.u->type, Wh.u->ne[0], Wh.u->ne[1], K);
        W.d = ggml_new_tensor_3d(ctx, Wh.d->type, Wh.d->ne[0], Wh.d->ne[1], K);
        buf = ggml_backend_alloc_ctx_tensors(ctx, be_gpu); CHECK(buf);
        for (int n = 1; n <= NU; n++) g[n] = build_moe(be_gpu, W.g, W.u, W.d, n);
        reset();
    }
    void reset() { slot_of.assign(NE, -1); expert_in.assign(K, -1); last_use.assign(K, -1); clock = 0; }
    void copy_in(int e, int s) {   // async H2D from pinned host copy; caller synchronizes
        for (auto [dst, src] : { std::pair{W.g, Wh.g}, {W.u, Wh.u}, {W.d, Wh.d} })
            ggml_backend_tensor_set_async(be_gpu, dst, (char *) src->data + e * src->nb[2], s * dst->nb[2], dst->nb[2]);
        if (expert_in[s] >= 0) slot_of[expert_in[s]] = -1;
        expert_in[s] = e; slot_of[e] = s;
    }
    int victim(const std::vector<char> & protect) {   // free slot first, else LRU among unprotected
        int best = -1;
        for (int s = 0; s < K; s++) { if (protect[s]) continue; if (expert_in[s] < 0) return s; if (best < 0 || last_use[s] < last_use[best]) best = s; }
        return best;
    }
    void free_() { for (int n = 1; n <= NU; n++) g[n].free_(); ggml_backend_buffer_free(buf); ggml_free(ctx); }
};

// one hybrid token. mode: 0 = overlap, 1 = serial (GPU then CPU). Returns output in y.
static Sample hybrid_token(Slots & S, const Token & t, int mode, float * y) {
    Sample sm{}; double t0 = now_us();
    int hid[NU], mid[NU]; float hw[NU], mw[NU]; int h = 0, m = 0;
    for (int i = 0; i < NU; i++) {
        int s = S.slot_of[t.ids[i]];
        if (s >= 0) { hid[h] = s; hw[h++] = t.w[i]; S.last_use[s] = S.clock; } else { mid[m] = t.ids[i]; mw[m++] = t.w[i]; }
    }
    S.clock++; sm.hits = h;
    const float * x = X[t.xi].data();
    if (mode == 0) {
        if (h) run_gpu_launch(S.g[h], x, hid, hw);
        double c0 = now_us();
        if (m) run_cpu(cpu_g[m], x, mid, mw, y_cpu_buf.data());
        double c1 = now_us();
        if (h) ggml_backend_synchronize(be_gpu);
        double c2 = now_us();
        sm.cpu = c1 - c0; sm.wait = c2 - c1;
    } else {
        double g0 = now_us();
        if (h) { run_gpu_launch(S.g[h], x, hid, hw); ggml_backend_synchronize(be_gpu); }
        double g1 = now_us();
        if (m) run_cpu(cpu_g[m], x, mid, mw, y_cpu_buf.data());
        sm.gpu = g1 - g0; sm.cpu = now_us() - g1;
    }
    for (int i = 0; i < D; i++) y[i] = (h ? h_y[i] : 0.f) + (m ? y_cpu_buf[i] : 0.f);
    sm.total = now_us() - t0;
    return sm;
}
// LRU admission after the token (between tokens): every miss is admitted; slots used by this token are protected.
static double lru_admit(Slots & S, const Token & t) {
    double t0 = now_us(); std::vector<char> prot(S.K, 0); int n = 0;
    for (int i = 0; i < NU; i++) { int s = S.slot_of[t.ids[i]]; if (s >= 0) prot[s] = 1; }
    for (int i = 0; i < NU; i++) {
        int e = t.ids[i]; if (S.slot_of[e] >= 0) continue;
        int s = S.victim(prot); if (s < 0) break;
        S.copy_in(e, s); S.last_use[s] = S.clock - 1; prot[s] = 1; n++;
    }
    if (n) ggml_backend_synchronize(be_gpu);
    return n ? now_us() - t0 : 0.0;
}
// upload-on-miss (llama.cpp moe-cache semantics): misses copied in before compute, all 8 computed on GPU. Needs K >= 8.
static Sample upload_token(Slots & S, const Token & t, float * y) {
    Sample sm{}; double t0 = now_us(); std::vector<char> prot(S.K, 0); int sid[NU], h = 0;
    for (int i = 0; i < NU; i++) { int s = S.slot_of[t.ids[i]]; if (s >= 0) { prot[s] = 1; h++; } }
    for (int i = 0; i < NU; i++) {
        int e = t.ids[i]; if (S.slot_of[e] < 0) { int s = S.victim(prot); CHECK(s >= 0); S.copy_in(e, s); prot[s] = 1; }
        sid[i] = S.slot_of[e]; S.last_use[sid[i]] = S.clock;
    }
    S.clock++; sm.hits = h;
    double a = now_us();
    run_gpu_launch(S.g[NU], X[t.xi].data(), sid, t.w); ggml_backend_synchronize(be_gpu);   // copies are on the same stream, ordered
    memcpy(y, h_y, D * 4);
    sm.total = now_us() - t0; sm.gpu = now_us() - a; sm.admit = a - t0;
    return sm;
}

// ---------------------------------------------------------------- fp64 reference
static std::vector<float> deq_g, deq_u, deq_d;   // [NE][F][D], [NE][F][D], [NE][D][F]
static void dequant_all() {
    auto deq = [](ggml_tensor * t, std::vector<float> & out) {
        auto * tr = ggml_get_type_traits(t->type); int64_t ne0 = t->ne[0], rows = t->ne[1] * t->ne[2];
        out.resize(ne0 * rows);
        for (int64_t r = 0; r < rows; r++) tr->to_float((char *) t->data + r * t->nb[1], out.data() + r * ne0, ne0);
    };
    deq(Wh.g, deq_g); deq(Wh.u, deq_u); deq(Wh.d, deq_d);
}
static void ref64(const Token & t, std::vector<double> & y) {
    y.assign(D, 0.0); const float * x = X[t.xi].data(); std::vector<double> a(F);
    for (int k = 0; k < NU; k++) {
        int e = t.ids[k];
        for (int f = 0; f < F; f++) {
            const float * rg = &deq_g[((size_t) e * F + f) * D], * ru = &deq_u[((size_t) e * F + f) * D];
            double sg = 0, su = 0; for (int i = 0; i < D; i++) { sg += (double) rg[i] * x[i]; su += (double) ru[i] * x[i]; }
            a[f] = sg / (1.0 + std::exp(-sg)) * su;
        }
        for (int o = 0; o < D; o++) {
            const float * rd = &deq_d[((size_t) e * D + o) * F]; double s = 0;
            for (int f = 0; f < F; f++) s += (double) rd[f] * a[f];
            y[o] += (double) t.w[k] * s;
        }
    }
}
static double rel_l2(const float * y, const std::vector<double> & r) {
    double n = 0, d = 0; for (int i = 0; i < D; i++) { double e = y[i] - r[i]; n += e * e; d += r[i] * r[i]; } return std::sqrt(n / d);
}
static double max_abs(const float * a, const float * b) { double m = 0; for (int i = 0; i < D; i++) m = std::max(m, (double) std::fabs(a[i] - b[i])); return m; }

// ---------------------------------------------------------------- results
struct Config {
    std::string name, stream, policy, mode; int K = -1, synth_m = -1;
    std::vector<Sample> s; std::vector<int> tok;   // token index into stream per sample
    std::vector<double> admit_us;                   // LRU between-token admission cost per token
    std::vector<int> admitted;
    std::vector<std::vector<float>> outs;           // output of the first timed pass (per stream token) for correctness
};
static double pct(std::vector<double> v, double p) { if (v.empty()) return NAN; std::sort(v.begin(), v.end()); return v[std::min(v.size() - 1, (size_t) (p * (v.size() - 1) + 0.5))]; }

int main(int argc, char ** argv) {
    std::string model = "/models/granite-3.1-1b-a400m-instruct-mixE4K.gguf", traces = "/traces", out = "/out/results.json";
    int layer = 12, threads = 8, passes = 2, synth_n = 300, warm = 30;
    for (int i = 1; i < argc; i++) {
        std::string a = argv[i]; auto nx = [&]() { CHECK(i + 1 < argc); return std::string(argv[++i]); };
        if (a == "--model") model = nx(); else if (a == "--traces") traces = nx(); else if (a == "--out") out = nx();
        else if (a == "--layer") layer = std::stoi(nx()); else if (a == "--threads") threads = std::stoi(nx());
        else if (a == "--passes") passes = std::stoi(nx()); else if (a == "--synth-n") synth_n = std::stoi(nx());
        else { fprintf(stderr, "unknown arg %s\n", a.c_str()); return 1; }
    }
    double T0 = now_us();
    // ---- load layer tensors from GGUF
    ggml_context * meta = nullptr; gguf_init_params gp = { true, &meta };
    gguf_context * gg = gguf_init_from_file(model.c_str(), gp); CHECK(gg);
    char nm[3][64]; const char * kinds[3] = { "ffn_gate_exps", "ffn_up_exps", "ffn_down_exps" };
    ggml_tensor * mt[3];
    for (int k = 0; k < 3; k++) { snprintf(nm[k], 64, "blk.%d.%s.weight", layer, kinds[k]); mt[k] = ggml_get_tensor(meta, nm[k]); CHECK(mt[k]); }
    char nn[64]; snprintf(nn, 64, "blk.%d.ffn_norm.weight", layer); ggml_tensor * mnorm = ggml_get_tensor(meta, nn); CHECK(mnorm && mnorm->type == GGML_TYPE_F32);
    D = (int) mt[0]->ne[0]; F = (int) mt[0]->ne[1]; CHECK(mt[0]->ne[2] == NE && mt[2]->ne[0] == F && mt[2]->ne[1] == D);
    for (int k = 0; k < 3; k++) fprintf(stderr, "%s type=%s ne=[%lld,%lld,%lld] bytes=%zu\n", nm[k], ggml_type_name(mt[k]->type),
        (long long) mt[k]->ne[0], (long long) mt[k]->ne[1], (long long) mt[k]->ne[2], ggml_nbytes(mt[k]));

    ggml_backend_load_all();
    be_cpu = ggml_backend_cpu_init(); CHECK(be_cpu);
    ggml_threadpool_params tpp = ggml_threadpool_params_default(threads);
    ggml_threadpool_t tp = ggml_threadpool_new(&tpp); CHECK(tp);
    ggml_backend_cpu_set_threadpool(be_cpu, tp); ggml_backend_cpu_set_n_threads(be_cpu, threads);
    be_gpu = ggml_backend_cuda_init(0); CHECK(be_gpu);

    // host (pinned) full copy
    ggml_init_params ip = { ggml_tensor_overhead() * 8, nullptr, true }; ggml_context * hctx = ggml_init(ip);
    Wh.g = ggml_dup_tensor(hctx, mt[0]); Wh.u = ggml_dup_tensor(hctx, mt[1]); Wh.d = ggml_dup_tensor(hctx, mt[2]);
    ggml_backend_buffer_t hbuf = ggml_backend_alloc_ctx_tensors_from_buft(hctx, ggml_backend_cuda_host_buffer_type()); CHECK(hbuf);
    {
        FILE * f = fopen(model.c_str(), "rb"); CHECK(f); size_t base = gguf_get_data_offset(gg);
        ggml_tensor * dst[3] = { Wh.g, Wh.u, Wh.d };
        for (int k = 0; k < 3; k++) {
            int64_t id = gguf_find_tensor(gg, nm[k]); CHECK(id >= 0);
            CHECK(fseeko(f, base + gguf_get_tensor_offset(gg, id), SEEK_SET) == 0);
            CHECK(fread(dst[k]->data, 1, ggml_nbytes(dst[k]), f) == ggml_nbytes(dst[k]));
        }
        std::vector<float> norm(D); int64_t id = gguf_find_tensor(gg, nn);
        CHECK(fseeko(f, base + gguf_get_tensor_offset(gg, id), SEEK_SET) == 0); CHECK(fread(norm.data(), 4, D, f) == (size_t) D);
        fclose(f);
        // synthetic activations: RMSNorm(N(0,1)) * real ffn_norm weight of this layer (the true input of the expert FFN is
        // rms_norm(h) * ffn_norm; h itself is synthetic -- see README)
        std::mt19937 rng(1234); std::normal_distribution<float> nd(0, 1);
        for (int v = 0; v < 64; v++) {
            std::vector<float> x(D); double ss = 0; for (auto & z : x) { z = nd(rng); ss += z * z; }
            float sc = 1.0f / std::sqrt((float) (ss / D) + 1e-6f); for (int i = 0; i < D; i++) x[i] *= sc * norm[i];
            X.push_back(x);
        }
    }
    // GPU full copy
    ggml_context * fctx = ggml_init(ip);
    Wf.g = ggml_dup_tensor(fctx, mt[0]); Wf.u = ggml_dup_tensor(fctx, mt[1]); Wf.d = ggml_dup_tensor(fctx, mt[2]);
    ggml_backend_buffer_t fbuf = ggml_backend_alloc_ctx_tensors(fctx, be_gpu); CHECK(fbuf);
    ggml_backend_tensor_set(Wf.g, Wh.g->data, 0, ggml_nbytes(Wh.g));
    ggml_backend_tensor_set(Wf.u, Wh.u->data, 0, ggml_nbytes(Wh.u));
    ggml_backend_tensor_set(Wf.d, Wh.d->data, 0, ggml_nbytes(Wh.d));
    const size_t expert_bytes = Wh.g->nb[2] + Wh.u->nb[2] + Wh.d->nb[2];
    fprintf(stderr, "expert bytes (gate+up+down) = %zu (%.3f MiB)\n", expert_bytes, expert_bytes / 1048576.0);

    // pinned staging
    ggml_backend_buffer_t sbuf = ggml_backend_buft_alloc_buffer(ggml_backend_cuda_host_buffer_type(), 4 * (3 * 1024 + 64));
    char * sb = (char *) ggml_backend_buffer_get_base(sbuf);
    h_x = (float *) sb; h_y = (float *) (sb + 4096 * 2); h_w = (float *) (sb + 4096 * 3); h_ids = (int32_t *) (sb + 4096 * 3 + 128);
    for (int n = 1; n <= NU; n++) cpu_g[n] = build_moe(be_cpu, Wh.g, Wh.u, Wh.d, n);
    ref_g = build_moe(be_gpu, Wf.g, Wf.u, Wf.d, NU);

    // ---- token streams
    std::vector<Token> stream, prefill;
    for (auto tag : { "prose", "code", "chat" }) {
        auto d = load_trace(traces + "/" + tag + ".jsonl", layer, "decode", tag); stream.insert(stream.end(), d.begin(), d.end());
        auto p = load_trace(traces + "/" + tag + ".jsonl", layer, "prefill", tag); prefill.insert(prefill.end(), p.begin(), p.end());
    }
    for (size_t i = 0; i < stream.size(); i++) stream[i].xi = i % X.size();
    fprintf(stderr, "layer %d: %zu decode tokens (stream), %zu prefill tokens (static profile)\n", layer, stream.size(), prefill.size());
    std::vector<int> freq(NE, 0); for (auto & t : prefill) for (int i = 0; i < NU; i++) freq[t.ids[i]]++;
    std::vector<int> rank(NE); for (int i = 0; i < NE; i++) rank[i] = i;
    std::stable_sort(rank.begin(), rank.end(), [&](int a, int b) { return freq[a] > freq[b]; });

    // synthetic streams: K=16 static (top-16 prefill profile); exactly m misses; weights taken from real decode tokens
    const int KS = 16; std::vector<std::vector<Token>> synth(NU + 1);
    {
        std::mt19937 rng(42); std::vector<int> res(rank.begin(), rank.begin() + KS), non(rank.begin() + KS, rank.end());
        for (int m = 0; m <= NU; m++) for (int i = 0; i < synth_n; i++) {
            Token t = stream[i % stream.size()]; std::shuffle(res.begin(), res.end(), rng); std::shuffle(non.begin(), non.end(), rng);
            std::vector<int> pick; for (int k = 0; k < NU - m; k++) pick.push_back(res[k]); for (int k = 0; k < m; k++) pick.push_back(non[k]);
            std::shuffle(pick.begin(), pick.end(), rng); for (int k = 0; k < NU; k++) t.ids[k] = pick[k];
            t.xi = i % X.size(); t.src = "synth"; synth[m].push_back(t);
        }
    }

    // ---- fp64 reference (parallel, untimed)
    dequant_all();
    auto refs_for = [&](const std::vector<Token> & v) {
        std::vector<std::vector<double>> r(v.size()); std::vector<std::thread> th; int nt = std::max(1, threads);
        for (int k = 0; k < nt; k++) th.emplace_back([&, k] { for (size_t i = k; i < v.size(); i += nt) ref64(v[i], r[i]); });
        for (auto & t : th) t.join(); return r;
    };
    auto R_stream = refs_for(stream);
    std::vector<std::vector<std::vector<double>>> R_synth(NU + 1);
    for (int m = 0; m <= NU; m++) R_synth[m] = refs_for(synth[m]);
    fprintf(stderr, "fp64 reference done (%.1f s since start)\n", (now_us() - T0) / 1e6);

    std::vector<Config> cfgs; std::vector<float> y(D);
    // runner over a stream: warmup pass (untimed, state reset before and after), then `passes` timed passes
    auto run_stream = [&](Config & c, const std::vector<Token> & v, std::function<Sample(const Token &, float *)> tok_fn,
                          std::function<void()> reset, std::function<double(const Token &, int &)> post) {
        reset(); for (size_t i = 0; i < std::min(v.size(), (size_t) warm); i++) { tok_fn(v[i], y.data()); if (post) { int n; post(v[i], n); } }
        c.outs.assign(v.size(), std::vector<float>(D));
        for (int p = 0; p < passes; p++) {
            reset();
            for (size_t i = 0; i < v.size(); i++) {
                Sample s = tok_fn(v[i], y.data());
                if (p == 0) c.outs[i] = y;
                c.s.push_back(s); c.tok.push_back((int) i);
                if (post) { int n = 0; double a = post(v[i], n); c.admit_us.push_back(a); c.admitted.push_back(n); }
            }
        }
    };
    auto gpu_ref_fn = [&](const Token & t, float * yy) {
        Sample s{}; double t0 = now_us(); run_gpu_launch(ref_g, X[t.xi].data(), t.ids, t.w); ggml_backend_synchronize(be_gpu);
        memcpy(yy, h_y, D * 4); s.total = s.gpu = now_us() - t0; s.hits = NU; return s;
    };
    auto cpu_all_fn = [&](const Token & t, float * yy) {
        Sample s{}; double t0 = now_us(); run_cpu(cpu_g[NU], X[t.xi].data(), t.ids, t.w, yy); s.total = s.cpu = now_us() - t0; s.hits = 0; return s;
    };
    auto noreset = [] {};

    // trace-driven
    { Config c; c.name = "gpu_ref"; c.stream = "trace"; c.policy = "all_gpu"; c.mode = "gpu"; c.K = 32; run_stream(c, stream, gpu_ref_fn, noreset, nullptr); cfgs.push_back(std::move(c)); }
    { Config c; c.name = "cpu_all"; c.stream = "trace"; c.policy = "all_cpu"; c.mode = "cpu"; c.K = 0; run_stream(c, stream, cpu_all_fn, noreset, nullptr); cfgs.push_back(std::move(c)); }
    for (int K : { 8, 12, 16, 24, 32 }) {
        Slots S; S.init(K);
        auto fill_static = [&] { S.reset(); for (int s = 0; s < K; s++) S.copy_in(rank[s], s); ggml_backend_synchronize(be_gpu); };
        for (int mode : { 0, 1 }) {
            Config c; c.name = std::string("hybrid_static_") + (mode ? "serial" : "overlap") + "_K" + std::to_string(K);
            c.stream = "trace"; c.policy = "static_prefill_profile"; c.mode = mode ? "serial" : "overlap"; c.K = K;
            run_stream(c, stream, [&](const Token & t, float * yy) { return hybrid_token(S, t, mode, yy); }, fill_static, nullptr);
            cfgs.push_back(std::move(c));
        }
        if (K < 32) {
            Config c; c.name = "hybrid_lru_overlap_K" + std::to_string(K); c.stream = "trace"; c.policy = "lru_admit_all_misses"; c.mode = "overlap"; c.K = K;
            run_stream(c, stream, [&](const Token & t, float * yy) { return hybrid_token(S, t, 0, yy); }, [&] { S.reset(); },
                       [&](const Token & t, int & n) { int before = 0; for (int e : S.expert_in) before += e >= 0; (void) before;
                           int miss = 0; for (int i = 0; i < NU; i++) miss += S.slot_of[t.ids[i]] < 0; n = miss; return lru_admit(S, t); });
            cfgs.push_back(std::move(c));
            Config u; u.name = "upload_lru_K" + std::to_string(K); u.stream = "trace"; u.policy = "lru_upload_on_miss"; u.mode = "gpu_upload"; u.K = K;
            run_stream(u, stream, [&](const Token & t, float * yy) { return upload_token(S, t, yy); }, [&] { S.reset(); }, nullptr);
            cfgs.push_back(std::move(u));
        }
        S.free_();
    }
    // synthetic controlled miss counts, K=16 static
    {
        Slots S; S.init(KS);
        auto fill_static = [&] { S.reset(); for (int s = 0; s < KS; s++) S.copy_in(rank[s], s); ggml_backend_synchronize(be_gpu); };
        for (int m = 0; m <= NU; m++) for (int mode : { 0, 1 }) {
            Config c; c.name = std::string("synth_") + (mode ? "serial" : "overlap") + "_m" + std::to_string(m);
            c.stream = "synth"; c.policy = "static_prefill_profile"; c.mode = mode ? "serial" : "overlap"; c.K = KS; c.synth_m = m;
            run_stream(c, synth[m], [&](const Token & t, float * yy) { return hybrid_token(S, t, mode, yy); }, fill_static, nullptr);
            cfgs.push_back(std::move(c));
        }
        // components: CPU-only m experts, GPU-only h experts (single graphs, sync), same tokens
        for (int m = 1; m <= NU; m++) {
            Config c; c.name = "cpu_only_n" + std::to_string(m); c.stream = "synth"; c.policy = "component"; c.mode = "cpu"; c.synth_m = m;
            run_stream(c, synth[m], [&](const Token & t, float * yy) { Sample s{}; double t0 = now_us(); run_cpu(cpu_g[m], X[t.xi].data(), t.ids, t.w, yy); s.total = s.cpu = now_us() - t0; return s; }, noreset, nullptr);
            c.outs.clear(); cfgs.push_back(std::move(c));
            Config g; g.name = "gpu_full_only_n" + std::to_string(m); g.stream = "synth"; g.policy = "component"; g.mode = "gpu"; g.synth_m = m;
            MoeG gg2 = build_moe(be_gpu, Wf.g, Wf.u, Wf.d, m);
            run_stream(g, synth[m], [&](const Token & t, float * yy) { Sample s{}; double t0 = now_us(); run_gpu_launch(gg2, X[t.xi].data(), t.ids, t.w); ggml_backend_synchronize(be_gpu); memcpy(yy, h_y, D * 4); s.total = s.gpu = now_us() - t0; return s; }, noreset, nullptr);
            gg2.free_(); g.outs.clear(); cfgs.push_back(std::move(g));
        }
        S.free_();
    }
    // H2D admission micro-benchmark: one expert (gate+up+down slices), pinned vs pageable source, 300 reps each
    std::vector<double> h2d_pinned, h2d_pageable;
    {
        Slots S; S.init(8); std::vector<char> pageable(expert_bytes);
        for (int r = 0; r < 330; r++) {
            int e = r % NE; double t0 = now_us(); S.copy_in(e, r % 8); ggml_backend_synchronize(be_gpu); double dt = now_us() - t0;
            if (r >= 30) h2d_pinned.push_back(dt);
        }
        for (int r = 0; r < 330; r++) {
            int s = r % 8; double t0 = now_us(); size_t off = 0;
            for (auto dst : { S.W.g, S.W.u, S.W.d }) { ggml_backend_tensor_set(dst, pageable.data() + off, s * dst->nb[2], dst->nb[2]); off += dst->nb[2]; }
            double dt = now_us() - t0; if (r >= 30) h2d_pageable.push_back(dt);
        }
        S.free_();
    }

    // ---- correctness
    // per token: e_x = rel-L2(x, fp64). Rule: e_hybrid <= 1.5 * max(e_gpu_ref, e_cpu_all) + 1e-6 for every token, and the two
    // pure endpoints must be bit-identical (all-hit hybrid == gpu_ref graph kernels; zero-hit == cpu_all kernels).
    std::ostringstream J; J.precision(6); J << std::fixed;
    auto & G = cfgs[0]; auto & C = cfgs[1];
    std::vector<double> eg(stream.size()), ec(stream.size());
    for (size_t i = 0; i < stream.size(); i++) { eg[i] = rel_l2(G.outs[i].data(), R_stream[i]); ec[i] = rel_l2(C.outs[i].data(), R_stream[i]); }
    J << "{\n\"meta\":{\"model\":\"" << model << "\",\"layer\":" << layer << ",\"threads\":" << threads << ",\"passes\":" << passes
      << ",\"warmup_tokens\":" << warm << ",\"stream_tokens\":" << stream.size() << ",\"expert_bytes\":" << expert_bytes
      << ",\"types\":[\"" << ggml_type_name(mt[0]->type) << "\",\"" << ggml_type_name(mt[1]->type) << "\",\"" << ggml_type_name(mt[2]->type) << "\"]"
      << ",\"static_rank\":["; for (int i = 0; i < NE; i++) J << (i ? "," : "") << rank[i]; J << "],\"label\":\"UNSCORED/exploratory\"},\n";
    J << "\"h2d_one_expert_us\":{\"pinned_median\":" << pct(h2d_pinned, .5) << ",\"pinned_p95\":" << pct(h2d_pinned, .95)
      << ",\"pageable_median\":" << pct(h2d_pageable, .5) << ",\"pageable_p95\":" << pct(h2d_pageable, .95) << ",\"pinned\":[";
    for (size_t i = 0; i < h2d_pinned.size(); i++) J << (i ? "," : "") << h2d_pinned[i]; J << "],\"pageable\":[";
    for (size_t i = 0; i < h2d_pageable.size(); i++) J << (i ? "," : "") << h2d_pageable[i]; J << "]},\n\"configs\":[\n";
    bool all_ok = true;
    fprintf(stderr, "\n%-32s %6s %9s %9s %9s %9s %9s %8s %10s %s\n", "config", "hit%", "med_us", "p95_us", "gpu_med", "cpu_med", "wait_med", "admit", "maxrel", "check");
    for (size_t ci = 0; ci < cfgs.size(); ci++) {
        auto & c = cfgs[ci]; std::vector<double> tot, gpu, cpu, wait; double hits = 0;
        for (auto & s : c.s) { tot.push_back(s.total); gpu.push_back(s.gpu); cpu.push_back(s.cpu); wait.push_back(s.wait); hits += s.hits; }
        double hit = hits / (c.s.size() * (double) NU);
        // correctness
        std::string chk = "n/a"; double maxrel = NAN, maxabs_ref = NAN; int fails = 0, n = 0;
        if (!c.outs.empty()) {
            const auto & R = c.stream == "trace" ? R_stream : R_synth[c.synth_m];
            maxrel = 0; maxabs_ref = 0;
            for (size_t i = 0; i < c.outs.size(); i++) {
                double e = rel_l2(c.outs[i].data(), R[i]); maxrel = std::max(maxrel, e); n++;
                if (c.stream == "trace") {
                    maxabs_ref = std::max(maxabs_ref, max_abs(c.outs[i].data(), G.outs[i].data()));
                    if (e > 1.5 * std::max(eg[i], ec[i]) + 1e-6) fails++;
                } else if (e > 2e-2) fails++;   // synthetic: no per-token gpu/cpu endpoints stored; loose absolute bound, see README
            }
            chk = fails ? "FAIL" : "ok";
            if (c.name == "hybrid_static_overlap_K32" || c.name == "hybrid_static_serial_K32") {   // all hits -> must equal gpu_ref bitwise
                if (maxabs_ref != 0.0) chk = "FAIL(not bit-identical to gpu_ref)"; else chk += ",bitwise==gpu_ref";
            }
            if (chk.rfind("FAIL", 0) == 0) all_ok = false;
        }
        double admit_med = c.admit_us.empty() ? 0 : pct(c.admit_us, .5); double admit_mean = 0, adm_n = 0;
        for (size_t i = 0; i < c.admit_us.size(); i++) { admit_mean += c.admit_us[i]; adm_n += c.admitted[i]; }
        if (!c.admit_us.empty()) { admit_mean /= c.admit_us.size(); adm_n /= c.admit_us.size(); }
        fprintf(stderr, "%-32s %6.1f %9.1f %9.1f %9.1f %9.1f %9.1f %8.1f %10.2e %s\n", c.name.c_str(), hit * 100, pct(tot, .5), pct(tot, .95),
            pct(gpu, .5), pct(cpu, .5), pct(wait, .5), admit_mean, maxrel, chk.c_str());
        J << (ci ? ",\n" : "") << "{\"name\":\"" << c.name << "\",\"stream\":\"" << c.stream << "\",\"policy\":\"" << c.policy << "\",\"mode\":\"" << c.mode
          << "\",\"K\":" << c.K << ",\"synth_misses\":" << c.synth_m << ",\"n\":" << c.s.size() << ",\"hit_rate\":" << hit
          << ",\"total_us_median\":" << pct(tot, .5) << ",\"total_us_p95\":" << pct(tot, .95) << ",\"gpu_us_median\":" << pct(gpu, .5)
          << ",\"cpu_us_median\":" << pct(cpu, .5) << ",\"wait_us_median\":" << pct(wait, .5)
          << ",\"admit_us_mean_per_token\":" << admit_mean << ",\"admit_us_median_per_token\":" << admit_med << ",\"admitted_mean_per_token\":" << adm_n
          << ",\"check\":\"" << chk << "\",\"check_tokens\":" << n << ",\"check_fails\":" << fails
          << ",\"max_rel_l2_vs_fp64\":" << (std::isnan(maxrel) ? -1 : maxrel) << ",\"max_abs_vs_gpu_ref\":" << (std::isnan(maxabs_ref) ? -1 : maxabs_ref);
        auto arr = [&](const char * k, std::function<double(const Sample &)> f) { J << ",\"" << k << "\":["; for (size_t i = 0; i < c.s.size(); i++) J << (i ? "," : "") << f(c.s[i]); J << "]"; };
        arr("total_us", [](const Sample & s) { return s.total; }); arr("gpu_us", [](const Sample & s) { return s.gpu; });
        arr("cpu_us", [](const Sample & s) { return s.cpu; }); arr("wait_us", [](const Sample & s) { return s.wait; });
        arr("admit_in_token_us", [](const Sample & s) { return s.admit; });
        J << ",\"hits\":["; for (size_t i = 0; i < c.s.size(); i++) J << (i ? "," : "") << c.s[i].hits; J << "]";
        if (!c.admit_us.empty()) { J << ",\"admit_between_tokens_us\":["; for (size_t i = 0; i < c.admit_us.size(); i++) J << (i ? "," : "") << c.admit_us[i]; J << "]"; }
        J << "}";
    }
    // endpoint error distribution
    J << "\n],\n\"endpoint_rel_l2_vs_fp64\":{\"gpu_ref_median\":" << pct(eg, .5) << ",\"gpu_ref_max\":" << pct(eg, 1) << ",\"cpu_all_median\":" << pct(ec, .5)
      << ",\"cpu_all_max\":" << pct(ec, 1) << "},\n\"all_checks_ok\":" << (all_ok ? "true" : "false") << "\n}\n";
    std::ofstream(out) << J.str();
    fprintf(stderr, "endpoint rel-L2 vs fp64: gpu_ref median %.2e max %.2e | cpu_all median %.2e max %.2e\n", pct(eg, .5), pct(eg, 1), pct(ec, .5), pct(ec, 1));
    fprintf(stderr, "H2D one expert: pinned median %.1f us p95 %.1f | pageable median %.1f us\n", pct(h2d_pinned, .5), pct(h2d_pinned, .95), pct(h2d_pageable, .5));
    fprintf(stderr, "ALL CHECKS %s; wrote %s; wall %.1f s\n", all_ok ? "OK" : "FAILED", out.c_str(), (now_us() - T0) / 1e6);
    return all_ok ? 0 : 2;
}

